  if(m.type==='paletteIndexMigrationOutput'){const status=migrationHost?.querySelector('[data-migration-body] > p');if(status)status.textContent='Reviewed output verified. Active SFF unchanged; retained migration remains available.';return}
  if(m.type==='paletteBulkGallery'){paletteBulkState=m;renderBulkGallery();return}
  if(m.type==='paletteBulkGalleryOutput'){const status=bulkHost?.querySelector('[data-bulk-body] > p');if(status)status.textContent='Bulk copies/proposal independently verified. Active SFF unchanged; retained plan remains available.';return}
  if(m.type==='paletteTemporaryLifecycle'){paletteTemporaryState=m;renderTemporaryLifecycle();return}
  if(m.type==='paletteTemporaryLifecycleOutput'){paletteTemporaryState=paletteTemporaryState||{};renderTemporaryLifecycle();return}
  if(m.type==='paletteTemporaryProposal'){const blocked=m.cleanup?.blocked||[],eligible=m.cleanup?.eligible||[];alert(m.message+'\\nEligible: '+eligible.length+' · blocked: '+blocked.length+(blocked.length?'\\n'+blocked.map(item=>item.paletteId+': '+item.reasons.join('; ')).join('\\n'):''));return}
  if(m.type==='paletteWorkshopCertification'){paletteCertificationState=m;const status=document.querySelector('[data-certification-status]');if(status)status.textContent=(m.readOnly?'Certification ledger is read-only: '+m.error:'Certification revision '+m.revision+' · '+m.physicalStatus.replace('-', ' ')+' · release-ready: no');return}
  if(m.type==='paletteWorkspaceSession'){const session=m.session;paletteWorkspaceSession=session;const status=document.getElementById('browser_paletteWorkflowStatus')||document.getElementById('browser_stagedPaletteStatus'),choice=session.selection?.sprite,restored=model.sprites.find(item=>item.archiveIndex===choice?.physicalIndex&&item.group===choice.group&&item.number===choice.number);if(restored&&selected?.archiveIndex!==restored.archiveIndex){selected=restored;group=restored.group;anchor=spriteKey(restored);render()}if(status)status.textContent='Preview: '+session.facts.preview+' · Staged: '+session.facts.staged+' · Embedded: '+session.facts.embedded+' · Built: '+session.facts.builtOutput+' · Adoption: '+session.facts.adoption+(session.stale?' · APPLY BLOCKED ('+session.staleReasons.join(', ')+')':'');renderMigrationWorkspace();renderBulkGallery();return}
  if(m.type==='paletteBuildState'){const status=document.getElementById('browser_stagedPaletteStatus')||document.getElementById('browser_paletteWorkflowStatus');if(status&&m.result)status.textContent=m.result.status==='adopted'?'Palette build verified and applied. No staged changes remain.':m.result.status==='validated-test-candidate'?'Built-in test candidate validated. Active SFF unchanged; reviewed plan retained.':m.result.status==='adopted-cleanup-required'?'SFF applied; staged-plan cleanup requires recovery. Plan retained.':'Active SFF unchanged; reviewed plan retained.';return}
  if(m.type==='paletteLibraryList'){const select=document.getElementById('browser_paletteLibrarySelect');if(!select)return;select.textContent='';const chosen=new Set((m.selected||[]).map(value=>String(value).toLowerCase()));for(const item of m.items||[]){const option=document.createElement('option');option.value=item.path;option.textContent=item.label;option.selected=chosen.has(String(item.path).toLowerCase());select.append(option)}if(!(m.items||[]).length){const option=document.createElement('option');option.value='';option.textContent='No ACT or indexed PNG palettes found';select.append(option)}const pathEl=document.getElementById('browser_paletteLibraryPath');if(pathEl)pathEl.textContent=(m.root||'No folder selected.')+(m.manualCount?' · '+m.manualCount+' manually selected file'+(m.manualCount===1?'':'s'):'');const staged=document.getElementById('browser_stagedPaletteStatus');if(staged)staged.textContent=(m.staged||[]).length?(m.staged||[]).map(item=>item.group+','+item.number+' · '+(item.kind==='alias'?'alias of '+item.targetGroup+','+item.targetNumber:item.name)).join(' | '):'No palettes staged for the next build.';const count=(m.staged||[]).length,workflow=document.getElementById('browser_paletteWorkflowStatus'),finish=document.getElementById('browser_finishPaletteBuild');if(workflow&&!paletteWorkspaceSession)workflow.textContent='Active target: '+model.filename+' · Embedded/saved palettes: '+model.palettes.length+' · Staged plan: '+count+(count?' · Build required; active SFF unchanged':' · No build pending');if(finish)finish.disabled=!count;return}
  if(m.type==='userPaletteList'){const select=document.getElementById('browser_userPaletteSelect');if(!select)return;select.textContent='';for(const item of m.items||[]){const option=document.createElement('option');option.value=item.id;option.textContent=item.name+(item.parent?' · child of '+item.parent:'');select.append(option)}if(!(m.items||[]).length){const option=document.createElement('option');option.value='';option.textContent='No user palettes saved';select.append(option)}const context=document.getElementById('browser_userPaletteContext'),status=document.getElementById('browser_userPaletteStatus');if(context)context.textContent=(m.context?.displayName||m.context?.characterId||'Character')+' · '+(m.context?.defPath?'DEF found':'DEF not found')+' · '+((m.context?.runtimeSlots||[]).length?(m.context.runtimeSlots||[]).map(slot=>'pal'+slot.number+' → '+slot.raw).join(' | '):'runtime slot not configured');if(status)status.textContent=m.root+' · '+(m.items||[]).length+' named save(s).';return}
  if(m.type==='referencePaletteList'){const select=document.getElementById('browser_referencePaletteSelect');if(!select)return;select.textContent='';for(const item of m.items||[]){const option=document.createElement('option');option.value=item.id;option.textContent=item.name+' · '+item.kind;option.selected=item.id===m.focusedId;select.append(option)}if(!(m.items||[]).length){const option=document.createElement('option');option.value='';option.textContent='No reference palettes loaded';select.append(option)}const status=document.getElementById('browser_referencePaletteStatus');if(status)status.textContent=(m.items||[]).length?(m.items.length+' reference palette(s) loaded. Select several for batch adaptation.'):'Nothing loaded.';return}
